-- =====================================================================
--  Doctor directory — বাংলাদেশ (189 entries)
--  Source: supabase/doctors_source.json → build_doctor_seed.mjs (auto-generated)
--  আগে migration_003_doctor_directory.sql চালান। বারবার চালানো নিরাপদ (upsert)।
-- =====================================================================

on conflict (lower(name), hospital_name, coalesce(branch, '')) do update
  set degrees = excluded.degrees,
      designation = excluded.designation,
      specialty = excluded.specialty,
      city = excluded.city,
      phone = excluded.phone,
      phone_type = excluded.phone_type,
      source_url = excluded.source_url,
      updated_at = now();

-- hospitals table-এর সাথে link (নাম মিললে)
update public.doctor_directory d set hospital_id = h.id
from public.hospitals h
where d.hospital_id is null and h.name = case d.hospital_name
  when 'Bangladesh Medical University' then 'Bangladesh Medical University (formerly BSMMU)'
  when 'Chittagong Medical College Hospital' then 'Chattogram Medical College Hospital'
  when 'LABAID Cardiac Hospital' then 'LABAID Specialized Hospital'
  when 'Ibn Sina Trust' then 'Ibn Sina Specialized Hospital, Dhanmondi'
  when 'Popular Diagnostic Centre, Uttara Garib E Newaz (Sector-13)' then 'Popular Diagnostic Centre, Uttara Sector 13'
  when 'Popular Diagnostic Centre, Uttara Jashim Uddin (Sector-04)' then 'Popular Diagnostic Centre, Uttara Sector 4'
  else d.hospital_name end;
